import { afterEach, describe, expect, it, vi } from 'vitest';
vi.mock('server-only', () => ({}), { virtual: true });
const { validateCouponCode } = await import('../../../task-a3-unit-tests/real/lib/coupons');

type RecordData = { id: string; code: string; name: string; description: null; discount_type: 'percentage' | 'fixed'; discount_value: number; minimum_amount: number; maximum_discount: number | null; usage_limit: number | null; usage_count: number | null; user_usage_limit: number | null; valid_from: string | null; valid_until: string | null; is_active: boolean; applies_to_product_id: string | null };
const record = (changes: Partial<RecordData> = {}): RecordData => ({ id: 'c1', code: 'SAVE', name: 'Save', description: null, discount_type: 'fixed', discount_value: 1000, minimum_amount: 0, maximum_discount: null, usage_limit: null, usage_count: 0, user_usage_limit: 1, valid_from: null, valid_until: null, is_active: true, applies_to_product_id: null, ...changes });
function fakeDb(data: RecordData | null = record(), usageCount = 0) { const cq: any = {}; cq.select = vi.fn(() => cq); cq.eq = vi.fn(() => cq); cq.maybeSingle = vi.fn().mockResolvedValue({ data, error: null }); let n = 0; const uq: any = {}; uq.select = vi.fn(() => uq); uq.eq = vi.fn(() => ++n === 2 ? Promise.resolve({ count: usageCount, error: null }) : uq); const from = vi.fn((table: string) => table === 'coupons' ? cq : uq); return { client: { from } as any, from }; }
async function apply(data: RecordData | null, subtotal = 10000, usageCount = 0, items?: Array<{ productId: string; price: number; quantity: number }>) { const db = fakeDb(data, usageCount); return { result: await validateCouponCode({ supabase: db.client, code: 'SAVE', subtotal, userId: 'user-1', items }), db }; }
afterEach(() => { vi.useRealTimers(); vi.restoreAllMocks(); });

describe('A-4 refined acceptance boundary', () => {
  it('loads the real server module through the test-only marker stub', () => { expect(validateCouponCode).toBeTypeOf('function'); });
  it.each([[record({ discount_type: 'percentage', discount_value: 20 }), 2000, 8000], [record({ discount_type: 'fixed', discount_value: 1500 }), 1500, 8500]] as const)('returns exact amounts for valid coupons', async (data, discountAmount, finalAmount) => { expect((await apply(data)).result).toMatchObject({ discountAmount, finalAmount }); });
  it.each([['', 'user-1', 400, '쿠폰 코드를 입력해주세요.'], ['SAVE', '', 401, '로그인이 필요합니다.']] as const)('rejects auth input before DB', async (code, userId, status, error) => { const from = vi.fn(); expect(await validateCouponCode({ supabase: { from } as any, code, subtotal: 10000, userId })).toEqual({ error, status }); expect(from).not.toHaveBeenCalled(); });
  it('rejects missing, expired, and exhausted coupons under a fixed clock', async () => { expect((await apply(null)).result).toEqual({ error: '유효하지 않은 쿠폰 코드입니다.', status: 404 }); vi.useFakeTimers(); vi.setSystemTime(new Date('2026-08-17T12:00:00+09:00')); expect((await apply(record({ valid_until: '2026-08-16' }))).result).toEqual({ error: '만료된 쿠폰입니다.', status: 400 }); expect((await apply(record({ user_usage_limit: 1 }), 10000, 1)).result).toEqual({ error: '이미 사용 한도를 채운 쿠폰입니다.', status: 400 }); });
  it('accepts minimum equality and rejects one won below', async () => { expect((await apply(record({ minimum_amount: 10000 }), 10000)).result).toMatchObject({ discountAmount: 1000, finalAmount: 9000 }); expect((await apply(record({ minimum_amount: 10000 }), 9999)).result).toEqual({ error: '최소 주문 금액 10,000원 이상이어야 합니다.', status: 400 }); });
  it('caps a percentage discount', async () => { expect((await apply(record({ discount_type: 'percentage', discount_value: 50, maximum_discount: 2000 }))).result).toMatchObject({ discountAmount: 2000, finalAmount: 8000 }); });
  it('uses trusted items passed at the current API boundary instead of client subtotal', async () => { const items = [{ productId: 'P1', price: 6000, quantity: 2 }]; expect(items.reduce((sum, item) => sum + item.price * item.quantity, 0)).toBe(12000); expect((await apply(record({ discount_type: 'percentage', discount_value: 20 }), 999999, 0, items)).result).toMatchObject({ discountAmount: 2400, finalAmount: 9600 }); });
  it('creates independent fake clients and call histories', async () => { const first = fakeDb(record()); const second = fakeDb(record()); expect(first.client).not.toBe(second.client); await validateCouponCode({ supabase: first.client, code: 'SAVE', subtotal: 10000, userId: 'user-1' }); expect(first.from).toHaveBeenCalled(); expect(second.from).not.toHaveBeenCalled(); });
});

