function fixedClock(iso: string) { const RealDate = globalThis.Date; const ms = RealDate.parse(iso); class FixedDate extends RealDate { constructor(value?: string | number) { super(value === undefined ? ms : value); } static now() { return ms; } } globalThis.Date = FixedDate as DateConstructor; return () => { globalThis.Date = RealDate; }; }
