Given('쿠폰은 {int}원 정액 할인이고 최소 주문금액은 {int}원이며 종료일은 {string}이다', function(this: CouponWorld, value: number, minimum: number, until: string) { this.coupon = makeRecord(this, 'fixed', value, minimum, null, until); });
Given('DB에 쿠폰이 없다', function(this: CouponWorld) { this.coupon = null; }); Given('사용자 사용 한도는 {int}회이고 사용 횟수는 {int}회이다', function(this: CouponWorld, limit: number, count: number) { assert.ok(this.coupon); this.coupon.user_usage_limit = limit; this.usageCount = count; });
